<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;require ROOT.'/core/uploads.php';$error='';$id=(int)($_GET['id']??0);$p=$id?one('SELECT * FROM products WHERE id=?',[$id]):null;if($id&&!$p){http_response_code(404);exit('Produto não encontrado.');}
if(is_post()){verify_csrf();try{$name=input('name',150);$category=input('category',40);$description=input('description',10000);$features=input('features',6000);$price=input('price',30);if($name===''||!in_array($category,['website','launcher','shopping','panel','module'],true))throw new InvalidArgumentException('Nome ou categoria inválida.');$amount=$price===''?null:parse_price($price);db()->beginTransaction();$visible=isset($_POST['visible'])?1:0;if($p)run('UPDATE products SET name=?,category=?,description=?,features=?,price=?,visible=? WHERE id=?',[$name,$category,$description,$features,$amount,$visible,$id]);else{run('INSERT INTO products (name,category,description,features,price,visible,created_at) VALUES (?,?,?,?,?,?,?)',[$name,$category,$description,$features,$amount,$visible,date('Y-m-d H:i:s')]);$id=(int)db()->lastInsertId();}save_upload($id,null);audit('produto_salvo','Produto #'.$id);db()->commit();flash('Produto salvo no catálogo.');go('admin/produtos.php?id='.$id);}catch(InvalidArgumentException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();throw $ex;}}
require ROOT.'/includes/panel.php';?><div class="toolbar"><h1>Produtos e catálogo.</h1><a class="primary btn" href="<?=e(url('admin/produtos.php?novo=1'))?>">+ Adicionar produto</a></div><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;if($p||isset($_GET['novo'])):?><form method="post" enctype="multipart/form-data"><div class="grid-two"><?php csrf();?><label class="field">Nome<input name="name" required maxlength="150" value="<?=e($p['name']??'')?>"></label><label class="field">Categoria<select name="category"><?php foreach(['website'=>'Website','launcher'=>'Launcher','shopping'=>'Shopping','panel'=>'Painel','module'=>'Módulo'] as $k=>$v):?><option value="<?=$k?>" <?=($p['category']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="field">Preço em R$ (vazio = orçamento)<input name="price" placeholder="299,90" value="<?=e(isset($p['price'])?number_format((float)$p['price'],2,',',''):'')?>"></label><label class="field">Arquivo de entrega / atualização (ZIP/PDF/TXT/PNG/JPG, até 5 MB)<input type="file" name="file" accept=".zip,.pdf,.txt,.jpg,.jpeg,.png"></label></div><label class="field">Descrição<textarea name="description" maxlength="10000"><?=e($p['description']??'')?></textarea></label><label class="field">Recursos (um por linha)<textarea name="features" maxlength="6000"><?=e($p['features']??'')?></textarea></label><label class="check"><input type="checkbox" name="visible" <?=($p['visible']??1)?'checked':''?>>Visível na loja</label><button class="primary">Salvar produto</button></form><?php if($p):?><h2>Arquivos deste produto</h2><?php foreach(rows('SELECT id,name,size FROM files WHERE product_id=? ORDER BY id DESC',[$id]) as $f):?><p class="muted"><a href="<?=e(url('baixar.php?id='.$f['id']))?>"><?=e($f['name'])?></a> • <?=number_format($f['size']/1024,1)?> KB</p><?php endforeach;endif;else:?><div class="table-wrap"><table><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Visível</th><th>Ação</th></tr><?php foreach(rows('SELECT * FROM products ORDER BY id DESC') as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td><?=e(money($p['price']))?></td><td><?=$p['visible']?'Sim':'Não'?></td><td><a href="<?=e(url('admin/produtos.php?id='.$p['id']))?>">Editar ↗</a></td></tr><?php endforeach;?></table></div><?php endif;require ROOT.'/includes/endpanel.php';?>
